-- Product-wide UI vocabulary for the exact-phrase compatibility translator.
--
-- Explicit translation keys remain the preferred API.  These entries also
-- expose their English values through /api/v1/i18n/phrases/{locale}, allowing
-- legacy page chrome to be translated without ever submitting tenant data to
-- an external translation service.  Only exact catalogue matches are changed.

create temporary table seed_global_ui_i18n(
  key_path text primary key,
  module_code text not null,
  description text not null,
  en text not null,
  de text not null,
  ru text not null
);

insert into seed_global_ui_i18n(key_path, module_code, description, en, de, ru) values
